// Host build: resetting an overlay's variables when it is loaded (overlay.c; the table is generated by
// tools/host_order.py). See docs/host.md.
#ifndef HOST_OVERLAY_H
#define HOST_OVERLAY_H

typedef void (*HostOverlayCtor)(void);

typedef struct {
    unsigned id;
    char *data, *dataEnd;            // its initialised data (in gdata)
    char *bss, *bssEnd;              // its bss (in gbss)
    HostOverlayCtor *init, *initEnd;  // its static constructors, in the DS's .sinit order
} HostOverlayRanges;

extern const HostOverlayRanges gHostOverlays[];
extern const unsigned gHostOverlayCount;

// FS_StartOverlay: overlay id was loaded
void HostOverlay_Load(unsigned id);

#endif
